<script setup lang="ts">
import { onMounted, ref } from 'vue';import { apiSeguridad } from '@/utils/seguridad'
const roles=ref<any[]>([]),permisos=ref<any[]>([]),nombre=ref(''),descripcion=ref(''),seleccionados=ref<number[]>([]),error=ref('');const cargar=async()=>{try{[roles.value,permisos.value]=await Promise.all([apiSeguridad('/roles'),apiSeguridad('/permisos')])}catch(e:any){error.value=e.message}};const guardar=async()=>{try{await apiSeguridad('/roles',{method:'POST',body:JSON.stringify({nombre:nombre.value,descripcion:descripcion.value,permiso_ids:seleccionados.value})});nombre.value=descripcion.value='';seleccionados.value=[];cargar()}catch(e:any){error.value=e.message}};onMounted(cargar)
</script><template><VCard><VCardItem><VCardTitle>Roles</VCardTitle><VCardSubtitle>Incluye los roles Administrador y Usuario creados para cada empresa y departamento.</VCardSubtitle></VCardItem><VCardText><VAlert v-if="error" type="error">{{error}}</VAlert><VTextField v-model="nombre" label="Nombre del rol"/><VTextField v-model="descripcion" label="Descripción"/><VSelect v-model="seleccionados" :items="permisos" item-title="descripcion" item-value="id" label="Permisos" multiple chips/><VBtn class="mb-4" @click="guardar">Crear rol</VBtn><VDataTable :items="roles" :headers="[{title:'Empresa',key:'empresa_id'},{title:'Departamento',key:'departamento'},{title:'Rol',key:'nombre'},{title:'Descripción',key:'descripcion'},{title:'Estado',key:'estado'}]"><template #item.empresa_id="{item}">{{item.empresa_id||'General'}}</template><template #item.departamento="{item}">{{item.departamento||'General'}}</template></VDataTable></VCardText></VCard></template>
